#include <iostream>
using namespace std;
void selectionSort(int arr[], int size) { for (int i = 0; i < size - 1; i++) { int minIdx = i; for (int j = i + 1; j < size; j++) if (arr[j] < arr[minIdx]) minIdx = j; int temp = arr[i]; arr[i] = arr[minIdx]; arr[minIdx] = temp; } } int main() { int n; cout << "Enter elements: "; cin >> n; int arr[n]; for (int i = 0; i < n; i++) { cout << "Element " << i + 1 << ": "; cin >> arr[i]; } selectionSort(arr, n); cout << "\nSorted: "; for (int i = 0; i < n; i++) cout << arr[i] << " "; cout << endl; return 0; }